// Flatten Notion rows into short records with stable short ids the agent can cite.
const txt = p => (p?.title ?? p?.rich_text ?? []).map(t => t.plain_text).join('');
const sel = p => p?.select?.name ?? null;

const clients = $('Notion: Clients').first().json.results.map((row, i) => ({
  ref: `C${i + 1}`, name: txt(row.properties['Client']), tier: sel(row.properties['Tier']),
  arr_eur: row.properties['ARR (EUR)']?.number ?? null, status: sel(row.properties['Status']),
  segment: sel(row.properties['Segment']), renewal: row.properties['Renewal date']?.date?.start ?? null,
}));
const feedback = $('Notion: Client feedback').first().json.results.map((row, i) => ({
  ref: `F${i + 1}`, request: txt(row.properties['Request']), client: sel(row.properties['Client']),
  quote: txt(row.properties['Quote']), blocks: sel(row.properties['Blocks']),
  received: row.properties['Received']?.date?.start ?? null, url: row.url,
}));
const linear = ($('Linear: client request issues').first().json.data?.issues?.nodes ?? []).map(i => ({
  ref: i.identifier, title: i.title, state: i.state?.name, url: i.url,
}));
const input = $('Called by orchestrator').first().json;
return [{ json: { feedback_text: input.feedback_text, client_hint: input.client_hint, clients, feedback, linear } }];

