// Deterministic demand sizing: the agent picks the matches, code does the arithmetic.
const data = $('Compact records').first().json;
const out = $json.output;
const byName = Object.fromEntries(data.clients.map(c => [c.name, c]));
const requester = data.clients.find(c => c.ref === out.client_ref) ?? null;

const matches = data.feedback.filter(f => out.similar_feedback_refs.includes(f.ref));
const linearMatches = data.linear.filter(l => out.similar_linear_refs.includes(l.ref));

const names = new Set(matches.map(f => f.client).filter(n => byName[n]));
if (requester) names.add(requester.name);
const asking = [...names].map(n => byName[n]);

const arr = asking.reduce((s, c) => s + (c.arr_eur ?? 0), 0);
const tiers = asking.map(c => c.tier).filter(Boolean);
const blockers = [...new Set(matches.map(f => f.blocks).filter(b => b && b !== 'None'))];

return [{ json: {
  specialist: 'request',
  client: requester?.name ?? null, client_tier: requester?.tier ?? null, client_arr_eur: requester?.arr_eur ?? null,
  request_title: out.request_title, quote: out.quote,
  similar_feedback: matches.map(f => ({ ref: f.ref, request: f.request, client: f.client, url: f.url })),
  similar_linear: linearMatches,
  demand: { clients_asking: asking.length, client_names: asking.map(c => c.name), combined_arr_eur: arr,
            tier1_clients: tiers.filter(t => t === 'Tier 1').length, blocks: blockers },
  confidence: out.confidence, reasoning: out.reasoning,
} }];
